pts = [-100, -80, -60, -40, -20, 0, 20, 40, 60, 80, 100]
vals = [4, 5, 11, 23, 29, 32, 31, 21, 14, 4, 4]

def f(y):
    if y <= -100 or y >= 100:
        return 0.0
    for i in range(len(pts)-1):
        if pts[i] <= y <= pts[i+1]:
            t = (y - pts[i]) / (pts[i+1] - pts[i])
            return vals[i] * (1 - t) + vals[i+1] * t
    return 0.0

for p in range(40, 52):
    ys = [i * 0.5 for i in range(int(p * 2) + 1)]
    totals = []
    for y in ys:
        tot = sum(f(y - k * p) for k in range(-10, 11))
        totals.append(tot)
    min_t, max_t, mean_t = min(totals), max(totals), sum(totals)/len(totals)
    print(f"pitch={p:2d}: mean={mean_t:5.1f}, min={min_t:5.1f}, max={max_t:5.1f}, ripple={(max_t-min_t)/mean_t*100:4.1f}%")
'

